("math1-sub-048","choice","区域 D：0≤x≤1，0≤y≤x，则 ∫∫D x dxdy =？","A","1/3;1/2;1/4;1/6","第1步：∫∫D x dxdy=∫(0,1) dx ∫(0,x) x dy。\n第2步：=∫(0,1) x·x dx=∫(0,1) x² dx。\n第3步：=1/3。\n结论：选 A。",2,"重积分","直角坐标与极坐标计算"),
("math1-sub-049","choice","用极坐标计算 ∫∫D √(x²+y²) dxdy（D：x²+y²≤1）等于？","B","2π/3;2π/3;π/3;π","第1步：极坐标 x=rcosθ，y=rsinθ，面积元 dxdy=r dr dθ。\n第2步：原式=∫(0,2π)dθ ∫(0,1) r·r dr=2π·[r³/3](0,1)。\n结论：=2π/3，选 B。",2,"重积分","直角坐标与极坐标计算"),
("math1-sub-050","choice","将 ∫(0,1)dx∫(0,x) f(x,y)dy 化为极坐标（先 θ 后 r）后，r 的范围是？","D","0≤r≤cosθ 且 θ 从 0 到 π/2;0≤r≤1;0≤r≤sinθ;0≤r≤1/cosθ 且 θ 从 0 到 π/4","第1步：区域 D：0≤x≤1，0≤y≤x，即直线 y=0、y=x 与 x=1 围成。\n第2步：极坐标下 θ 从 0 到 π/4，r 从 0 到 1/cosθ（x=1 即 r cosθ=1）。\n结论：选 D。",3,"重积分","直角坐标与极坐标计算"),
("math1-sub-051","choice","∫∫D (x²+y²) dxdy（D：1≤x²+y²≤4）等于？","C","15π;10π;15π/2;5π","第1步：极坐标：∫(0,2π)dθ ∫(1,2) r²·r dr。\n第2步：=2π·[r⁴/4](1,2)=2π·(16/4-1/4)。\n结论：=2π·15/4=15π/2，选 C。",3,"重积分","直角坐标与极坐标计算"),
