("math1-sub-058","choice","设 Ω 为球体 x²+y²+z²≤R²，则 ∫∫∫Ω dV =？","A","4πR³/3;2πR³;πR³;4πR²","第1步：∫∫∫Ω dV 为球体体积。\n第2步：球体体积公式 V=4πR³/3。\n结论：选 A。",1,"重积分","三重积分"),
("math1-sub-059","choice","Ω：0≤x≤1，0≤y≤1，0≤z≤1，则 ∫∫∫Ω x dV =？","B","1/4;1/2;1;1/3","第1步：∫∫∫Ω x dV=∫(0,1)dx∫(0,1)dy∫(0,1)x dz。\n第2步：=∫(0,1) x dx·1·1=[x²/2](0,1)。\n结论：=1/2，选 B。",2,"重积分","三重积分"),
("math1-sub-060","choice","用球坐标，球体 x²+y²+z²≤1 上的积分 ∫∫∫Ω dV 中 r 的范围是？","D","0≤r≤1/2;0≤r≤π;0≤r≤2;0≤r≤1","第1步：球坐标下 r 为到原点的距离。\n第2步：单位球体内部 0≤r≤1。\n结论：选 D。",1,"重积分","三重积分"),
