import json, io
out = []
for id_, t, stem, ans, opts, exp, diff, ch, sub in Q:
    q = {"id": id_, "project": "math1", "type": t, "stem": stem, "answer": ans,
         "explanation": exp, "source": "海螺补题", "chapter": ch,
         "difficulty": diff, "kind": "mock", "reviewStatus": "approved", "sub": sub}
    if t == "choice":
        q["options"] = opts.split(";")
    out.append(q)
io.open(r"D:\考研数学项目\data\patch_math1_b.json", "w", encoding="utf-8").write(json.dumps(out, ensure_ascii=False, indent=1))
